<template><div class="profile-page"><v-row><v-col cols="12" md="4"><v-card class="pa-6 text-center rounded-xl" elevation="1"><v-avatar size="120" color="#165134"><v-img v-if="photoUrl" :src="photoUrl"/><span v-else class="white--text text-h4">{{initials}}</span></v-avatar><h2 class="mt-4">{{profile.name}}</h2><div class="grey--text">{{profile.email}}</div><div class="grey--text">{{profile.branch&&profile.branch.name}}</div><v-file-input v-model="photo" class="mt-5" outlined dense accept="image/png,image/jpeg,image/webp" label="Profile picture"/><v-btn block color="#165134" dark :loading="photoSaving" :disabled="!photo" @click="uploadPhoto">Update Picture</v-btn></v-card></v-col><v-col cols="12" md="8"><v-card class="pa-6 rounded-xl mb-4" elevation="1"><div class="text-h6 mb-4">Profile Information</div><v-text-field v-model="profile.name" outlined label="Full Name"/><v-text-field v-model="profile.email" outlined disabled label="Email"/><v-btn color="#165134" dark :loading="saving" @click="saveProfile">Save Profile</v-btn></v-card><v-card class="pa-6 rounded-xl" elevation="1"><div class="text-h6 mb-4">Change Password</div><v-text-field v-model="password.current_password" outlined :type="show?'text':'password'" label="Current Password"/><v-text-field v-model="password.password" outlined :type="show?'text':'password'" label="New Password"/><v-text-field v-model="password.password_confirmation" outlined :type="show?'text':'password'" label="Confirm New Password"/><v-checkbox v-model="show" label="Show passwords"/><v-btn color="#165134" dark :loading="passwordSaving" @click="changePassword">Change Password</v-btn></v-card></v-col></v-row></div></template><script>
import api from '../../services/api'
export default{name:'Profile',data(){return{profile:{},photo:null,saving:false,photoSaving:false,passwordSaving:false,show:false,password:{current_password:'',password:'',password_confirmation:''}}},computed:{initials(){return(this.profile.name||'U').split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase()},photoUrl(){return this.profile.profile_photo?'/storage/'+this.profile.profile_photo:null}},mounted(){this.load()},methods:{async load(){const r=await api.get('/profile');this.profile=r.data.data},async saveProfile(){this.saving=true;try{const r=await api.put('/profile',{name:this.profile.name});this.profile=r.data.data;this.$store.commit('auth/UPDATE_USER',r.data.data);this.$root.$emit('show-success',r.data.message)}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to update profile.')}finally{this.saving=false}},async uploadPhoto(){this.photoSaving=true;try{const f=new FormData();f.append('photo',this.photo);const r=await api.post('/profile/photo',f);this.profile=Object.assign({},this.profile,r.data.data);this.$store.commit('auth/UPDATE_USER',r.data.data);this.photo=null;this.$root.$emit('show-success',r.data.message)}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to upload picture.')}finally{this.photoSaving=false}},async changePassword(){this.passwordSaving=true;try{const r=await api.put('/profile/password',this.password);this.password={current_password:'',password:'',password_confirmation:''};this.$root.$emit('show-success',r.data.message)}catch(e){this.$root.$emit('show-error',(e.response&&e.response.data&&e.response.data.message)||'Unable to change password.')}finally{this.passwordSaving=false}}}}</script><style scoped>.profile-page{max-width:1100px;margin:auto}</style>